const CARDS = {};
function card(owner, id, n, s, t, x, o = {}) { CARDS[id] = Object.assign({ owner, id, n, s, t, x }, o); }
const B = v => ({ val: v, play: e => e.boost(v) });
const W = (v, unblock) => ({ val: v, play: e => e.weaken(v, { unblock }) });
const SW = v => ({ val: v, play: e => e.swap(v) });
const DF = (v, els, half) => ({ def: { v, els, half } });
const CN = (pred, els, extra = {}) => ({ cancel: Object.assign({ pred, els }, extra) });
